import type { GuidedLab } from '../../../quizBank';

export const GUIDED: Record<string, GuidedLab> = {"labex-git-apply-the-latest-stash":{"intro":"In Git, a stash is a way to save changes that are not yet ready to be committed. It allows you to temporarily save your work and switch to another branch or commit without losing any changes. When you're ready to continue working on your changes, you can apply the stash to your working directory. In this challenge, you will learn how to apply the latest stash to your Git repository.","steps":[{"title":"Apply the Latest Stash","body":["You are working on a project in your Git repository and have made some changes that are not yet ready to be committed. However, you need to switch to another branch or commit to work on a different feature. You don't want to lose your changes, so you decide to stash them. Later, when you're ready to continue working on your changes, you need to apply the latest stash to your working directory.","To apply the latest stash to your Git repository, follow these steps:","• List of your stashes. You should see one stash in the list. • Apply the latest stash to your working directory. • Check the README.md file to see that your changes have been applied.","This is the result of running the cat README.md command:"],"code":[]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit stash apply <stash>\n```\n\n```shell\ncd git-playground\ngit stash apply # Applies the latest stash\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-apply-a-stash":{"intro":"In this challenge, you will learn how to use Git stash to temporarily save changes, switch to another branch, and then apply the stashed changes to continue working on your original branch.","steps":[{"title":"Apply a stash","body":["You are working on a feature branch in the git-playground repository and you need to switch to another branch to work on a bug fix. However, you have some changes that are not ready to be committed yet. You want to save these changes and switch to the other branch. Once you are done with the bug fix, you want to apply the stash and continue working on your feature branch.","The changes have been stashed on the feature-branch branch, and the stash message is \"my changes\".","• Change to the git-playground directory. • Switch to the master branch and stash it after fixing the bug, the stash message is \"fix the bug\". Fix the bug by updating the contents of the file1.txt file to \"hello,world\". • Switch to the feature-branch branch, look at the list of stashes, and apply the stash whose information is \"my changes\".","This is the contents of the README.md file:"],"code":[{"lang":"text","text":"# git-playground\nGit Playground\nsome changes"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit stash apply <stash>\n```\n\n```shell\ncd git-playground\ngit checkout master\necho \"hello,world\" > file1.txt\ngit stash save \"fix the bug\"\ngit checkout feature-branch\ngit stash apply stash@{1} # Applies `stash@{1}`\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-automate-upstream-branch-creation":{"intro":"In a collaborative project, it is common to have multiple developers working on different branches of the same repository. When a developer pushes their changes to a branch that does not exist on the remote repository, the push will fail. This is where upstream branch creation comes in handy. By enabling automatic upstream branch creation on push, developers can avoid the hassle of manually creating the branch on the remote repository.","steps":[{"title":"Automate Upstream Branch Creation","body":["Automate Upstream Branch Creation","As a developer, you want to automate the process of creating upstream branches on push to avoid the hassle of manually creating the branch on the remote repository.","To complete the challenge, you will use the Git repository git-playground in your GitHub account to automatically create an upstream branch at push time from a fork of https://github.com/labex-labs/git-playground.git.","• Clone the repository, navigate to the directory and configure the identity. • Enable automatic upstream branch creation on push. • Create and switch to a branch called new-feature, add the hello.txt file and write \"hello,world\" in it, add it to the staging area and commit it with the message \"Added hello.txt\". • Push your changes to a new branch called new-feature, which does not exist in the remote repository."],"code":[]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit config --global push.default current\n```\n\n```shell\n# Fork from https://github.com/labex-labs/git-playground.git\ngit clone https://github.com/your-username/git-playground.git\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\ngit config --global push.default current\ngit checkout -b new-feature\ngit push\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-find-branches-containing-a-commit":{"intro":"In Git, branches are used to develop features or isolate changes made to a project. Sometimes, you may need to find out which branches contain a specific commit. This challenge will test your ability to use Git commands to find branches containing a commit.","steps":[{"title":"Find Branches Containing a Commit","body":["Find Branches Containing a Commit","You have been given a Git repository named https://github.com/labex-labs/git-playground. Your task is to find all branches that contain a hash with the commit message \"Added file2.txt\".","• Change into the repository directory. • Find all branches that contain a hash with the commit message \"Added file2.txt\"."],"code":[{"lang":"shell","text":"* master\nnew-branch\nnew-branch-1\nnew-branch-2"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit branch --contains <commit>\n```\n\n```shell\ncd git-playground\ngit branch --contains d22f46b\n# a hash with the commit message \"Added file2.txt\".\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-find-branches-not-containing-a-commit":{"intro":"Git is a popular version control system that allows developers to track changes in their codebase. One of the useful features of Git is the ability to create branches, which are essentially separate copies of the codebase that can be modified independently. However, sometimes it can be difficult to keep track of which branches contain certain commits. In this challenge, you will learn how to find branches that do not contain a specific commit.","steps":[{"title":"Find Branches Not Containing a Commit","body":["Find Branches Not Containing a Commit","You are working on a project with multiple branches, and you need to find all the branches that do not contain a specific commit. This can be useful if you want to make sure that a certain change has been applied to all branches, or if you want to know which branches are outdated and need to be updated.","For this challenge, we will be using the Git repository named https://github.com/your-username/git-playground.","• Clone this repository to your local machine. • Once you have cloned the repository, navigate to the directory. • Create and switch to a new-branch branch and make some code changes on that branch and then commit it, the commit message is \"Create a new-branch branch\". • Check the hash of the commit message \"Create a new-branch branch\". • Finds all branches that do not contain a hash with the commit message \"Create a new-branch branch\"."],"code":[]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit branch --no-contains <commit>\n```\n\n```shell\n# Fork from https://github.com/labex-labs/git-playground.git\ngit clone https://github.com/your-username/git-playground.git\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\ngit checkout -b new-branch\necho \"hello,world\" > file1.txt\ngit commit -am \"Create a new-branch branch\"\ngit log\ngit branch --no-contains 31c5ac20129151af1\n# \"31c5ac20129151af1\" is the hash of the commit message \"Create a new-branch branch\".\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-change-the-remote-url":{"intro":"In Git, a remote is a version of your repository that is hosted on a server or another computer. When you clone a repository, Git automatically creates a remote called origin that points to the original repository. However, sometimes you may need to change the URL of the remote repository. This challenge will test your ability to change the remote URL using Git commands.","steps":[{"title":"Change the Remote URL","body":["You have cloned a repository from GitHub and made some changes to it. However, you now realize that you need to change the URL of the remote repository. This could be because the original repository has been moved to a different location, or because you want to push your changes to a different remote repository. Your task is to change the remote URL of the repository using Git commands.","Assume that you have cloned the repository https://github.com/labex-labs/git-playground to your local machine. To change the remote URL of the repository to https://github.com/your-username/git-playground.","The output should show the new URL instead of the old one:"],"code":[]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit remote set-url origin <url>\n\ngit remote -v #Use the command to view the current remote URL\n```\n\n```shell\ncd git-playground\ngit remote -v\ngit remote set-url origin https://github.com/your-username/git-playground\ngit remote -v\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-clone-missing-submodules":{"intro":"In Git, submodules are repositories within repositories. They allow you to include other repositories as dependencies in your project. When you clone a Git repository that contains submodules, the submodules are not automatically cloned. This can cause issues when trying to build or run the project. In this challenge, you will learn how to clone missing submodules and checkout commits.","steps":[{"title":"Clone Missing Submodules","body":["You are working on a project that contains submodules. When you clone the project, the submodules are not automatically cloned. This causes issues when trying to build or run the project. You need to clone the missing submodules and checkout the correct commits.","For this challenge, we will use the Git repository named https://github.com/git/git. This repository contains submodules that are not automatically cloned when you clone the repository.","To clone the missing submodules and checkout the correct commits, follow these steps:","• Change into the repository directory. • Initialize the submodules. • Checkout to the correct commit of the submodule, i.e. the master branch."],"code":[{"lang":"shell","text":"Submodule 'sha1collisiondetection' (https://github.com/cr-marcstevens/sha1collisiondetection.git) registered for path 'sha1collisiondetection'\nCloning into '/home/labex/project/git/sha1collisiondetection'...\nSubmodule path 'sha1collisiondetection': checked out '855827c583bc30645ba427885caa40c5b81764d2'"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit submodule update --init --recursive\n# Clones missing submodules and checks out commits\n```\n\n```shell\ncd git\ngit submodule update --init --recursive\ngit submodule foreach git checkout master\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-change-the-last-commit-s-author":{"intro":"In this challenge, you will learn how to change the author of the last commit in a Git repository without modifying the commit's contents.","steps":[{"title":"Change the Last Commit's Author","body":["Change the Last Commit's Author","You have just made a commit to your Git repository, but you realized that the author's name and email address are incorrect. You want to update the author's information without changing the contents of the commit. How can you achieve this using Git?","To change the last commit's author, you can use a command. This command allows you to modify the last commit in your Git repository.","• Navigate to the repository and configure Git's identity information using your GitHub account. • Change the author of the last commit to Duck Quackers, whose email address is cool.duck@qua.ck and save the contents. • Verify that the author's information has been updated."],"code":[{"lang":"shell","text":"commit d5a385cc354f3528472a215b66cbb7c628ba47d5\nAuthor: Duck Quackers <cool.duck@qua.ck>\nDate:   Wed Apr 26 14:16:25 2023 +0800\n\n    Added file2.txt"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit commit --amend --author=\"<name> <email>\"\n```\n\n```shell\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\ngit commit --amend --author=\"Duck Quackers <cool.duck@qua.ck>\"\n# The last commit's author is now `Duck Quackers`\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-configure-git-user-information":{"intro":"Git is a popular version control system used by developers to manage their code. When you make changes to a repository, Git tracks who made those changes. To do this, Git needs to know your user information, such as your name and email address. In this challenge, you will learn how to configure your user information for Git.","steps":[{"title":"Configure Git User Information","body":["Configure Git User Information","You have just started working on a new project and want to configure your user information for Git. You want to make sure that your name and email address are associated with any changes you make to the repository.","Your task is to configure your user information for the Git repository. For example, if your email address is jane.doe@example.com and your name is Jane Doe.","After completing the challenge, your can check your configuration by running the following command:"],"code":[{"lang":"bash","text":"git config --list"}]}],"commands":["git config --list"],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit config [--global] user.email <email>\ngit config [--global] user.name <name>\n```\n\n```shell\ncd git-playground\ngit config --global user.email \"jane.doe@example.com\"\ngit config --global user.name \"Jane Doe\"\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-copy-a-file-from-another-branch":{"intro":"In Git, branches are used to isolate development work without affecting other branches in the repository. Sometimes, you may need to copy a file from another branch to the current branch. This challenge will test your ability to copy a file from another branch using Git.","steps":[{"title":"Copy a File from Another Branch","body":["Copy a File from Another Branch","You are working on a project in a Git repository named https://github.com/labex-labs/git-playground.git. You have two branches named feature-1 and feature-2. You need to copy the file hello.txt from feature-1 branch to feature-2 branch.","• Navigate to the directory and configure the identity. • Create and switch to feature-1 branch and create a text file named hello.txt and write the string \"hello,world\" to it and commit the file with the message \"add hello.txt\". • Create and switch to feature-2 branch after switching to master branch. • Copy the hello.txt file from the feature-1 branch to the feature-2 branch and commit it with the commit message \"copy hello.txt\". • Verify that the hello.txt file has been copied to feature-2 branch.","You should see the hello.txt file in the list of files in the feature-2 branch:"],"code":[{"lang":"text","text":"-rw-r--r-- 1 labex labex 15 Jul 12 22:43 file1.txt\n-rw-r--r-- 1 labex labex 15 Jul 12 22:43 file2.txt\n-rw-r--r-- 1 labex labex 12 Jul 12 22:50 hello.txt\n-rw-r--r-- 1 labex labex 32 Jul 12 22:43 README.md"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit checkout <branch> <file>\n```\n\n```shell\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\ngit checkout -b feature-1\necho \"hello,world\" > hello.txt\ngit add .\ngit commit -m \"add hello.txt\"\ngit checkout master\ngit checkout -b feature-2\ngit checkout feature-1 hello.txt\ngit commit -am \"copy hello.txt\"\nll\n# `feature-2` branch now contains the hello.txt file from `feature-1`\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-create-a-new-branch":{"intro":"In Git, a branch is a lightweight movable pointer to a commit. Creating a new branch allows you to work on a new feature or bug fix without affecting the main codebase. In this challenge, you will learn how to create a new branch in Git.","steps":[{"title":"Create a New Branch","body":["For this challenge, fork the Git repository named https://github.com/labex-labs/git-playground into your GitHub account.You are working on a project in a Git repository named https://github.com/your-username/git-playground. You need to create a new branch named feature-1 to work on a new feature.","• Clone the repository, navigate to the directory and configure the identity. • Check the current branch. • Create a new branch named feature-1. • Verify that you are now on the feature-1 branch. • Push the changes to the remote repository.","This is what happens when you run the git branch -r command:","![git branch r command output](../assets/challenge-create-branch-step1-1.png)"],"code":[]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit checkout -b < branch > [-t < remote > / < branch > ]\n\ngit checkout -b feature-1\n# Local branch, without a remote tracking branch\ngit push -u origin feature-1\n\ngit checkout -b feature-1 -t origin/feature-1\n# Local branch and remote tracking branch with the same name\n```\n\n```shell\n# Fork from https://github.com/labex-labs/git-playground.git\ngit clone https://github.com/your-username/git-playground.git\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\ngit branch\ngit checkout -b feature-1\ngit branch\ngit push -u origin feature-1\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-create-an-empty-commit":{"intro":"In Git, a commit is a snapshot of the changes made to a repository. Each commit has a message that describes the changes made. Sometimes, you may need to create an empty commit with no changes to serve as a placeholder or to trigger a build process. In this challenge, you will learn how to create an empty commit in Git.","steps":[{"title":"Create an Empty Commit","body":["You need to create an empty commit in your Git repository. This can be useful in several scenarios, such as:","• Triggering a build process • Creating a placeholder commit • Marking a specific point in the repository's history","For this challenge, let's use the repository from https://github.com/labex-labs/git-playground.","This is where you run git log --name-status HEAD^..HEAD and the result:"],"code":[]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit commit --allow-empty -m <message>\n```\n\n```shell\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\ngit commit --allow-empty -m \"Empty commit\"\n# Creates an empty commit with the message \"Empty commit\"\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-create-a-fixup-commit":{"intro":"In Git, a fixup commit is a special type of commit that is used to fix a previous commit. It is typically used when you want to make a small change to a commit that has already been made, without having to create a new commit. Fixup commits are especially useful when you are working on a large project with many contributors, as they allow you to make small changes without disrupting the work of others.","steps":[{"title":"Create a Fixup Commit","body":["Suppose you are working on a project with several other developers, and you notice a small error in a commit that was made a few days ago. You want to fix the error, but you don't want to create a new commit and disrupt the work of the other developers. This is where fixup commits come in handy. By creating a fixup commit, you can make the necessary changes without creating a new commit, and the fixup commit will be automatically merged with the original commit during the next rebase.","Your task is to write the string \"hello,world\" to the hello.txt file and add it as a \"fixup\" commit to the commit with the message \"Added file1.txt\", so that it can be automatically merged in a subsequent rebase operation.","For this challenge, let's use the repository from https://github.com/labex-labs/git-playground.","• Navigate to the directory and configure the identity. • Create a hello.txt file, write \"hello,world\" in it and add it to the staging area. • Create a fixup commit for the hash of the \"Added file1.txt\" commit message. • Once you have created the fixup commit, you can automatically merge the fixup commit with the original commit during the next rebase. When opening the interactive editor, you don't need to change the text and save to exit."],"code":[{"lang":"shell","text":"[object Object]"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit commit --fixup <commit>\n```\n\n```shell\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\ngit log --oneline\necho \"hello,world\" > hello.txt\ngit add .\ngit commit --fixup cf80005\n# This is the hash of the commit message \"Added file1.txt\".\ngit rebase --interactive --autosquash HEAD~3\n# Now the fixup commit has been squashed\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-create-your-first-git-repository":{"intro":"Git is a popular version control system used by developers to manage their code. One of the first steps in using Git is to create a new repository. In this challenge, you will learn how to initialize a new Git repository.","steps":[{"title":"Create a New Repository","body":["You have been tasked with creating a new Git repository for a project. You need to set up all the configuration files needed by Git and ensure that the repository is properly initialized.","• Initialize a new Git repository named my_project in ~/project. • Verify that the .git directory has been created inside the my_project directory.","When you finish the tasks, the my_project directory should look like this:"],"code":[{"lang":"bash","text":"ls -a ~/project/my_project"},{"lang":"plaintext","text":".  ..  .git"}]}],"commands":["ls -a ~/project/my_project"],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ncd /home/labex/project\ngit init my_project # Initializes a repo in /home/labex/project/my_project\n```\n\nOr\n\n```shell\ncd /home/labex/project/my_project\ngit init # Initializes a repo in /home/labex/project/my_project\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-delete-a-branch":{"intro":"In Git, branches are used to develop features or isolate changes for a specific purpose. Once the changes are merged into the main branch, the branch has served its purpose and can be deleted. Deleting a branch in Git is a straightforward process.","steps":[{"title":"Delete a Branch","body":["You have created a local branch in your Git repository, and you no longer need it. You want to delete the branch to keep your repository clean and organized.","• Navigate to the cloned repository. • View current branches. • Delete the feature-1 branch. • Verify that the branch has been deleted.","This is the result of running the git branch command:"],"code":[{"lang":"text","text":"* master"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit branch -d <branch>\n```\n\n```shell\ncd git-playground\ngit branch\ngit branch -d feature-1 # Deletes the `feature-1` local branch\ngit branch\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-delete-detached-branches":{"intro":"When working with Git, it's common to create and switch to detached branches. These branches are not associated with any specific branch and are usually used for testing or experimentation. However, over time, these branches can accumulate and clutter your repository. In this challenge, you will learn how to delete all detached branches in your Git repository.","steps":[{"title":"Delete Detached Branches","body":["You have a Git repository with several detached branches that you no longer need. These branches are cluttering your repository and making it difficult to manage. You want to delete all detached branches to clean up your repository.","To complete this challenge, you will use the Git repository git-playground from your GitHub account, which comes from a fork of https://github.com/labex-labs/git-playground.git. Do not check \"Copy the master branch only\".","• Clone the repository, navigate to the directory and configure the identity. • Since there is a feature-branch branch in the remote repository, switch to feature-branch, which will cause the local feature-branch to track the feature-branch branch of the remote repository and delete the feature-branch branch in the remote repository. • View the trace relationship between local branches and the remote branches they track. • Switch back to the master branch. • Remove all detached branches from your local repository. • Verify that the detached branches have been deleted.","The output should only show the branches that are associated with a specific branch:"],"code":[{"lang":"shell","text":"* master d22f46b [origin/master] Added file2.txt"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit branch -vv | grep ': gone]' | awk '{print $1}' | xargs git branch -D\n```\n\n```shell\n# Fork from https://github.com/labex-labs/git-playground.git\ngit clone https://github.com/your-username/git-playground.git\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\ngit checkout feature-branch\ngit push origin --delete feature-branch\ngit checkout master\ngit branch\n# feature-branch\n# master\n# Assuming `feature-branch` is detached\ngit branch -vv | grep ': gone]' | awk '{print $1}' | xargs git branch -D\ngit branch\n# master\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-delete-merged-branches":{"intro":"When working on a project with Git, it's common to create and merge branches. However, over time, these branches can accumulate and clutter your local repository. Deleting merged branches is a good practice to keep your repository clean and organized.","steps":[{"title":"Delete Merged Branches","body":["Your task is to delete all local branches that have been merged into the master branch of the https://github.com/labex-labs/git-playground repository.","• Change to the repository directory. • List all local branches that have been merged into master. • Delete all merged branches. • List all branches again."],"code":[{"lang":"text","text":"* master"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit branch --merged master | awk '!/^[ *]*$/ && !/master/ {print $1}' | xargs git branch -d\n```\n\n```shell\ncd git-playground\ngit branch --merged\ngit branch --merged master | awk '!/^[ *]*$/ && !/master/ {print $1}' | xargs git branch -d\ngit branch\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-delete-a-remote-branch":{"intro":"In Git, a branch is a lightweight movable pointer to a commit. Branches are used to develop features, isolate changes, and experiment without affecting other parts of the repository. Remote branches are references to the state of branches on remote repositories. They are used to keep track of the progress of other developers' work and to collaborate on projects.","steps":[{"title":"Delete a Remote Branch","body":["Sometimes, you may need to delete a remote branch that is no longer needed. For example, if a feature branch has been merged into the main branch, you may want to delete the remote feature branch to keep the repository clean.","Suppose that a GitHub repository called git-playground has been cloned from your GitHub account, which comes from a fork of https://github.com/labex-labs/git-playground.git. You want to delete the remote branch named feature-branch that is no longer needed.","The output should not include the feature-branch remote branch:"],"code":[{"lang":"text","text":"origin/HEAD -> origin/master\norigin/master"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit push -d <remote> <branch>\n```\n\n```shell\n# Fork from https://github.com/labex-labs/git-playground.git\ngit clone https://github.com/your-username/git-playground.git\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\ngit checkout -b feature-branch\ngit push -u origin feature-branch\ngit branch -r\ngit push -d origin feature-branch # Deletes the `feature-branch` remote branch\ngit branch -r\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-disable-fast-forward-merging":{"intro":"Git is a powerful version control system that allows developers to collaborate on projects efficiently. One of the features of Git is fast forward merging, which allows Git to automatically merge branches that have no divergent commits. However, this feature can sometimes cause issues, especially when working on larger projects with multiple contributors. In this challenge, you will learn how to disable fast forward merging by default.","steps":[{"title":"Disable Fast Forward Merging","body":["By default, Git uses fast forward merging to merge branches that have no divergent commits. This means that if you have a branch with no new commits, Git will simply move the pointer of the branch you are merging into to the latest commit of the branch you are merging from. While this can be useful in some cases, it can also cause issues, especially when working on larger projects with multiple contributors. For example, if two developers are working on the same branch and both make changes, fast forward merging can cause conflicts that are difficult to resolve.","To disable fast forward merging, let's use the repository from https://github.com/labex-labs/git-playground.","• Navigate to the directory and configure the identity. • Create and switch to a branch called my-branch, create a hello.txt file and add \"hello,world\" to it, add it to the staging area and commit it with the message \"Added hello.txt\". • Disable fast forward merging for all branches. • Switch back to the master branch and merge the my-branch branch, save and exit without changing the text.","Now, Git will always create a merge commit, even if it is possible to fast forward:"],"code":[{"lang":"shell","text":"commit 6e17a776ab51a89ace069614b0caf1c07915a92c (HEAD -> master)\nMerge: ec5ea6d 6d7de91\nAuthor: xiaoshengyunan <@users.noreply.github.com>\nDate:   Mon Jul 17 13:30:44 2023 +0800\n\n    Merge branch 'my-branch'"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit config [--global] --add merge.ff false\n\ngit config --global --add merge.ff false\n```\n\n```shell\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\ngit checkout -b my-branch\necho \"hello,world\" > hello.txt\ngit add .\ngit commit -m \"Added hello.txt\"\ngit config --global --add merge.ff false\ngit checkout master\ngit merge my-branch\n# Will never fast forward even if it's possible\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-discard-uncommitted-changes":{"intro":"Git is a version control system that allows developers to track changes in their codebase. Sometimes, developers may make changes to their code that they later decide they don't want to keep. In such cases, it is necessary to discard these changes and revert to the last committed version of the code. This challenge will focus on discarding uncommitted changes in Git.","steps":[{"title":"Discard Uncommitted Changes","body":["You have made some changes to your local Git repository, but you have not yet committed them. However, you have decided that you no longer want to keep these changes and want to discard them. The problem is to find a way to discard all uncommitted changes to the current branch.","To complete this challenge, you will use the Git repository named https://github.com/labex-labs/git-playground directory. Follow the steps below:","• Navigate to the cloned repository. • See the changes you have made. • Discard all uncommitted changes. • Confirm that all changes have been discarded.","This is the result of running git status:"],"code":[{"lang":"shell","text":"On branch master\nYour branch is up to date with 'origin/master'.\n\nnothing to commit, working tree clean"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit reset --hard HEAD\n# Discards all unstaged changes\n```\n\n```shell\ncd git-playground\ngit status\ngit reset --hard HEAD\ngit status\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-discard-untracked-changes":{"intro":"When working with Git, it's common to have untracked changes in your working directory. These changes are files that Git is not currently tracking. Sometimes, you may want to discard these changes and start fresh. In this challenge, you will learn how to discard all untracked changes to the current branch.","steps":[{"title":"Discard Untracked Changes","body":["You are working on a project using Git and have made some changes to your working directory. However, you realize that you don't need these changes and want to discard them. You want to discard all untracked changes to the current branch.","To complete this challenge, you will use the Git repository named https://github.com/labex-labs/git-playground.","• Navigate to the repository directory. • Check the status of your working directory. • Discard all untracked changes to the current branch. • Check the status of your working directory again.","You should see the following output:"],"code":[{"lang":"shell","text":"On branch master\nYour branch is up to date with 'origin/master'.\n\nnothing to commit, working tree clean"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit clean -f -d\n# Discards all untracked changes\n```\n\n```shell\ncd git-playground\ngit status\ngit clean -f -d\ngit status\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-edit-git-configuration-file":{"intro":"Git is a popular version control system that allows developers to track changes in their codebase. Git configuration file is a file that contains settings that affect the behavior of Git. In this challenge, you will learn how to edit the Git configuration file using the Git text editor.","steps":[{"title":"Edit Git Configuration File","body":["As a developer, you may need to modify the Git configuration file to customize the behavior of Git. The Git configuration file is a plain text file that contains settings in the form of key-value pairs. The file can be edited using any text editor, but Git provides a built-in text editor that can be used to modify the configuration file.","In this example, we will use the Git repository named https://github.com/labex-labs/git-playground directory.","This is the result after completion:"],"code":[{"lang":"shell","text":"# This is Git's per-user configuration file.\n[user]\nname = labex_git\nemail = labex_git@example.com\n# Please adapt and uncomment the following lines:\n#   name =\n#   email = labex@64b8c76af840a200973e9d16.(none)"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit config --global -e\n```\n\n```shell\ncd git-playground\ngit config --global -e\n# Opens the git configuration file in the default git text editor\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-fetch-latest-changes-from-remote":{"intro":"Git is a popular version control system used for tracking changes in code. One of the key features of Git is the ability to work with remote repositories. In this challenge, you will learn how to fetch the latest changes from a remote repository using Git.","steps":[{"title":"Fetch Latest Changes from Remote","body":["Fetch Latest Changes from Remote","Suppose you are working on a project with a team of developers, and the project is stored in a remote repository. You want to get the latest changes from the remote repository without applying them to your local repository.","To demonstrate how to fetch the latest changes from a remote repository, we will use the Git repository git-playground from your GitHub account, which comes from a fork of https://github.com/labex-labs/git-playground.git.","• Clone the repository, navigate to the directory. • Find the git-playground repository in your account on the Github website, create and switch to a branch called fetch-branch, create a file called hello.txt, add \"hello, world\" and commit with the message \"Create hello.txt\". • View branches in remote repositories. • Fetch the latest changes from the remote repository. • View branches in remote repositories again and verify that the latest changes have been fetched."],"code":[{"lang":"shell","text":"commit f3125b4c99e0ef2ce58bc0b1287c966c9e68c577 (origin/fetch-branch)\nAuthor: xiaoshengyunan <131872312+xiaoshengyunan@users.noreply.github.com>\nDate:   Thu Jul 20 20:17:23 2023 +0800\n\n    Create hello.txt"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit fetch\n```\n\n```shell\nFork from https://github.com/labex-labs/git-playground.git\ngit clone https://github.com/your-username/git-playground.git\ncd git-playground\ngit branch -r\ngit fetch # Fetches the latest updates from the remote\ngit branch -r\ngit log origin/fetch-branch\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-find-lost-files":{"intro":"Git is a powerful version control system that allows developers to track changes to their codebase. However, sometimes files can become lost or accidentally deleted. In this challenge, you will learn how to use Git to find lost files and commits.","steps":[{"title":"Find Lost Files","body":["You have been working on a project in the git-playground repository. However, you have noticed that some files are missing and you are not sure when they were deleted or how to recover them. Your task is to use Git to find any lost files and commits in the repository.","• Navigate to the directory and configure the identity. • Create and switch a branch named one-branch, delete file2.txt and commit with the message \"Remove file2\". • Switch back to the master branch and delete the one-branch branch. • Find any lost files and commits. • Check the .git/lost-found directory to see if any lost files were recovered. • If any lost files were found, review them to determine if they are the missing files.","This is the result of running the ls .git/lost-found command:"],"code":[]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Step 1 Solution\n\nTo solve this challenge, you need to first create a \"lost\" commit and then use `git fsck` to find it. Here are the detailed steps:\n\n1.  First, navigate to the `git-playground` repository and configure your Git identity.\n\n    ```shell\n    cd /home/labex/project/git-playground\n    git config --global user.name \"labex\"\n    git config --global user.email \"labex@labex.io\"\n    ```\n\n2.  Create a new branch `one-branch`, and switch to it.\n\n    ```shell\n    git checkout -b one-branch\n    ```\n\n3.  On the new branch, delete the `file2.txt` and commit this change. This creates a new commit object.\n\n    ```shell\n    git rm file2.txt\n    git commit -m \"Remove file2\"\n    ```\n\n4.  Switch back to the `master` branch.\n\n    ```shell\n    git checkout master\n    ```\n\n5.  Now, delete the `one-branch` branch. Because this was the only branch pointing to the commit where `file2.txt` was deleted, that commit is now \"lost\" or \"dangling\".\n\n    ```shell\n    git branch -D one-branch\n    ```\n\n6.  Run `git fsck --lost-found`. This command will search for any dangling objects (like our lost commit) and restore them into the `.git/lost-found` directory.\n\n    ```shell\n    git fsck --lost-found\n    ```\n\n7.  Finally, list the contents of the `.git/lost-found` directory to verify that the lost commit has been found. You should see a `commit` object.\n\n    ```shell\n    ls .git/lost-found\n    ```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-update-remote-branch-after-rewriting-history":{"intro":"Git is a powerful version control system that allows developers to track changes made to their codebase. One of the key features of Git is the ability to rewrite history, which can be useful when you need to make changes to previous commits. However, rewriting history can cause issues when trying to push changes to a remote repository. In this challenge, you will learn how to update a remote branch after rewriting history locally.","steps":[{"title":"Update Remote Branch After Rewriting History","body":["Update Remote Branch After Rewriting History","When you rewrite history locally, you create a new commit with a different SHA-1 hash. This means that the commit history on your local branch is different from the commit history on the remote branch. If you try to push your changes to the remote branch, Git will reject the push because it will see the commit history as diverged. To solve this problem, you need to force an update of the remote branch.","To complete this challenge, you will use the Git repository git-playground from your GitHub account, which comes from a fork of https://github.com/labex-labs/git-playground.git.","• Clone the git-playground repository to your local machine. • Update a commit with the message \"Added file2.txt\" to a commit with the message \"Update file2.txt\". • Push changes from local branch to remote repository. • If you can't push it successfully, please force push it."],"code":[{"lang":"shell","text":"[object Object]"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit push -f\n```\n\n```shell\n# Fork from https://github.com/labex-labs/git-playground.git\ngit clone https://github.com/your-username/git-playground.git\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\ngit commit --amend # Update the commit message to \"Update file2.txt\".\ngit push\ngit push -f origin master\ngit log\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-configure-line-endings":{"intro":"In this challenge, you will learn how to configure line endings in a Git repository to ensure consistency and avoid conflicts when collaborating with a team of developers.","steps":[{"title":"Configure Line Endings","body":["You are working on a project with a team of developers, and you notice that some team members are using different line endings than others. This can cause issues when merging code and can lead to conflicts. You need to configure the line endings for the repository to ensure consistency and avoid conflicts.","To configure the line endings for the git-playground repository, follow these steps:","• Navigate to the directory where the git-playground repository is located (~/project/git-playground). • Configure the line endings to use UNIX line endings (\\n). • Verify that the line endings have been configured correctly.","To verify that the line endings have been configured correctly, you can use the following command:"],"code":[{"lang":"bash","text":"git config --get core.eol"}]}],"commands":["git config --get core.eol"],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit config core.eol [lf | crlf]\n```\n\n```shell\ncd ~/project/git-playground\ngit config core.eol lf # Configured to use UNIX line endings\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-list-all-git-aliases":{"intro":"Git is a powerful version control system that allows developers to manage their code and collaborate with others. One of the features of Git is the ability to create aliases, which are shortcuts for commonly used Git commands. Aliases can save time and make working with Git more efficient.","steps":[{"title":"List All Git Aliases","body":["As a developer, you may want to list all the Git aliases that have been set up on your system. This can be useful for several reasons, such as:","• Checking which aliases are available • Finding out what commands an alias is mapped to • Removing or modifying existing aliases","Let's say you have a Git repository named git-playground located at https://github.com/labex-labs/git-playground.","You have set up the following aliases:"],"code":[{"lang":"shell","text":"alias.st=status\nalias.co=checkout\nalias.rb=rebase"},{"lang":"shell","text":"st=status\nco=checkout\nrb=rebase"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit config -l | grep alias | sed 's/^alias\\.//g'\n```\n\n```shell\ncd git-playground\ngit config -l | grep alias | sed 's/^alias\\.//g'\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-tracking-code-changes-with-git":{"intro":"Git is a powerful version control system that allows developers to track changes to their codebase over time. One of the most useful features of Git is the ability to find the commit that introduced a bug. This can be incredibly helpful when trying to track down the source of a problem in your code.","steps":[{"title":"Manually Find the Commit that Introduced a Bug","body":["Manually Find the Commit that Introduced a Bug","Your task is to manually find the commit that introduced a bug in the git-playground repository. The repository can be found at https://github.com/labex-labs/git-playground.","To complete this challenge, you will need to perform a binary search through the commit history of the repository. You will need to mark commits as either \"good\" (bug-free) or \"bad\" (buggy) until you have narrowed down the commit that introduced the bug.","The error message is that the file2.txt file should print \"This is file2.txt.\" instead of \"This is file2.\"."],"code":[{"lang":"text","text":"d22f46ba8c2d4e07d773c5126e9c803933eb5898 is the first bad commit\ncommit d22f46ba8c2d4e07d773c5126e9c803933eb5898\nAuthor: Hang <huhuhang@users.noreply.github.com>\nDate:   Wed Apr 26 14:16:25 2023 +0800\n\n    Added file2.txt\n\n file2.txt | 1 +\n 1 file changed, 1 insertion(+)\n create mode 100644 file2.txt"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\n# ... some time later the bad commit will be printed\n```\n\n```shell\ncd git-playground\ngit bisect start\ngit bisect bad HEAD\ngit bisect good b00b937 # This is a hash of the commit message \"Initial commit\"\ncat file2.txt\ngit bisect good\ngit bisect reset\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-merge-a-branch":{"intro":"In this challenge, you will learn how to merge a branch into the current branch using Git, which is a crucial skill for managing changes and collaborating on projects.","steps":[{"title":"Merge a Branch","body":["Your task is to merge a branch into the current branch using Git. You will need to switch to the target branch and then merge the source branch into it. This can be useful when you want to combine changes from a feature-branch-A branch into the master branch of your project.","For this challenge, let's use the repository from https://github.com/labex-labs/git-playground.","• Navigate to the directory and configure the identity. • Create a feature-branch-A branch. Switch to it. • Add \"hello,world\" to the file2.txt file, add it to the staging area and commit it with the message \"fix file2.txt\". • Switch to the master branch. • Merge the feature-branch-A into the master branch. • Resolve any conflicts that may arise during the merge process.","This is the result of running git log:"],"code":[{"lang":"shell","text":"commit e2b80358ae6e4c3b8439cf111a4672a188739290 (HEAD -> master, feature-branch-A)\nAuthor: xiaoshengyunan <xiaoshengyunan@users.noreply.github.com>\nDate:   Fri Jul 21 18:51:00 2023 +0800\n\n    fix file2.txt"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit checkout <target-branch>\ngit merge <source-branch>\n```\n\n```shell\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\ngit checkout -b feature-branch-A\necho \"hello,world\" >> file2.txt\ngit add .\ngit commit -m \"fix file2.txt\"\ngit checkout master\ngit merge feature-branch-A # Merges the `feature-branch-A` branch into `master`\ngit log\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-git-collaborative-version-control":{"intro":"In this challenge, you will learn how to merge a branch into the current branch, creating a merge commit, using the Git version control system.","steps":[{"title":"Merge a Branch and Create a Merge Commit","body":["Merge a Branch and Create a Merge Commit","As a developer, you may need to merge a branch into the current branch, creating a merge commit. This can be a bit tricky if you're not familiar with Git. The problem is to merge a branch into the current branch, creating a merge commit, using the Git repository named https://github.com/labex-labs/git-playground directory.","For this challenge, let's use the repository from https://github.com/labex-labs/git-playground.","• Clone the repository, navigate to the directory and configure the identity. • Create and switch to a branch called feature-branch. • Add \"This is a new line.\" to the README.md file, add it to the staging area and commit it, the commit message is \"Add new line to README.md\". • Switch to the master branch. • Merge the feature-branch into the master branch,which will create a merge commit with the message \"Merge feature-branch\"."],"code":[{"lang":"shell","text":"ADD new line to README.md"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit checkout <target-branch>\ngit merge --no-ff -m <message> <source-branch>\n```\n\n```shell\ngit clone https://github.com/labex-labs/git-playground\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\ngit checkout -b feature-branch\necho \"This is a new line.\" >> README.md\ngit add .\ngit commit -am \"Add new line to README.md\"\ngit checkout master\ngit merge --no-ff -m \"Merge feature-branch\" feature-branch\n# Merges the `feature-branch` branch into `master` and creates a commit with the message \"Merge feature-branch\"\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-move-commits-to-a-new-branch":{"intro":"Git is a powerful version control system that allows developers to keep track of changes made to their codebase. One of the useful features of Git is the ability to move commits from one branch to another. This can be helpful when you realize that some changes you made to the master branch should have been made on a separate branch. In this challenge, you will learn how to move commits from the master branch to a new branch.","steps":[{"title":"Move Commits to a New Branch","body":["For this challenge, let's use the repository from https://github.com/labex-labs/git-playground. You have been working on a project in the master branch. You realize that some of the changes you made should have been made on a separate branch. You want to move these changes to a new branch called feature.","• Navigate to the repository directory and configure your GitHub identity. • Checkout the master branch. • Create a file called hello.txt, add \"hello, world\" to it, add it to the staging area and submit it with the message \"Added hello.txt\". • Create a new branch called feature without switching to it . • Undo the last commit on master. • Check the commit history on the master branch and the commit history on the feature branch to verify the results.","This is the result of running git log:"],"code":[{"lang":"shell","text":"commit 7969ab5d6606e2a40c9fd826c732206b835976e9 (HEAD -> feature)\nAuthor: xiaoshengyunan <@users.noreply.github.com>\nDate:   Fri Jul 21 20:19:22 2023 +0800\n\n    Added hello.txt"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit branch <branch>\ngit reset HEAD~1 --hard\ngit checkout <branch>\n```\n\n```shell\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\necho \"hello,world\" >> hello.txt\ngit add .\ngit commit -m \"Added hello.txt\"\ngit branch feature\n# `feature` branch is created containing the commit \"Added hello.txt\"\ngit reset HEAD~1 --hard # Remove the commit from `master`\ngit log\ngit checkout feature\ngit log # Verify that the changes are now in `feature`\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-applying-selective-git-commit-changes":{"intro":"Git is a powerful version control system that allows developers to manage their codebase efficiently. One of the most useful features of Git is the ability to cherry-pick changes from one or more commits. This allows developers to apply specific changes to their codebase without having to merge entire branches.","steps":[{"title":"Git Cherry-Pick","body":["As a developer, you are working on a project with multiple branches. You have identified a specific change that was made in a previous commit that you would like to apply to your current branch. However, you do not want to merge the entire branch as it contains other changes that you do not need.","For this challenge, let's use the repository from https://github.com/labex-labs/git-playground.","• Navigate to the directory and configure the identity. • Create and switch to a branch called one-branch, create a file called hello.txt, write \"hello,world\" in it, add it to the staging area and commit it with the message \"add hello.txt\". • Identify the hash of the commit created in the previous step to apply to the master branch. • Checkout the master branch and apply the change to the master branch. • Verify that the change has been applied to the master branch.","This is the result of running git log on the master branch:"],"code":[{"lang":"shell","text":"ADD hello.txt"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\n# Picks changes from the commits `3050fc0de`, `c191f90c7` and `0b552a6d4`\n\n# Picks changes from the commits in the range `3050fc0de` - `c191f90c7`\n```\n\n```shell\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\ngit checkout -b one-branch\necho \"hello,world\" > hello.txt\ngit add .\ngit commit -m \"add hello.txt\"\ngit log\ngit checkout master\ngit cherry-pick 1609c283ec86ee4\ngit log\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-pull-latest-changes-from-remote":{"intro":"Git is a popular version control system that allows developers to collaborate on projects and keep track of changes made to the codebase. One of the most important features of Git is the ability to pull the latest changes from a remote repository. In this challenge, you will learn how to pull the latest changes from a remote repository using Git.","steps":[{"title":"Pull Latest Changes from Remote","body":["Pull Latest Changes from Remote","You are working on a project with a team of developers, and you need to ensure that your local copy of the codebase is up to date with the latest changes made by your team members. To do this, you need to pull the latest changes from the remote repository.","For this challenge, we will be using the Git repository named https://github.com/labex-labs/git-playground.","• Change into the directory of the cloned repository. • Pull the latest changes from the master branch of the remote repository."],"code":[]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit pull\n\ngit pull origin master\n# The local `master` branch is now up to date with the remote branch\n```\n\n```shell\ncd git-playground\ngit pull origin master\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-purge-a-file-from-history":{"intro":"Git is a popular version control system that allows developers to track changes in their codebase. However, sometimes it becomes necessary to completely remove a file from the repository's history. This challenge will guide you through the process of purging a file from Git's history.","steps":[{"title":"Purge a file from history","body":["Suppose you accidentally committed a file containing sensitive information, such as API keys or passwords, to your Git repository. You realize that this file should never have been committed and want to completely remove it from the repository's history. However, simply deleting the file and committing the change will not remove it from the repository's history. The file will still be accessible in previous commits, which could pose a security risk.","To complete this challenge, you will use the Git repository git-playground from your GitHub account, which comes from a fork of https://github.com/labex-labs/git-playground.git. This repository contains a file named file1.txt that should never have been committed.Please purge file1.txt from the repository's history.","• Clone the repository to your local machine from https://github.com/your-username/git-playground. • Navigate to the directory and configure the identity. • Delete the file from the repository's index. • Rewrite the repository's history, removing all instances of file1.txt. • Force push the changes to the remote repository.","After completing these steps, file1.txt will be completely removed from the repository's history and after running git log --remotes, you will not see the commit on file1.txt."],"code":[]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit filter-branch --force --index-filter \\\n  \"git rm --cached --ignore-unmatch <path>\" \\\n  --prune-empty --tag-name-filter cat -- --all\ngit push --all < remote > --force\n```\n\n```shell\n# Fork from https://github.com/labex-labs/git-playground.git\ngit clone https://github.com/your-username/git-playground.git\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\ngit rm --cached --ignore-unmatch file1.txt\ngit filter-branch --force --index-filter \"git rm --cached --ignore-unmatch file1.txt\" --prune-empty --tag-name-filter cat -- --all\n# Purges `file1.txt` from history\ngit push origin --force --all\n# Force pushes the changes to the remote repository\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-push-local-changes-to-remote":{"intro":"In this challenge, you will learn how to push local changes to a remote Git repository, ensuring that your local branch is up-to-date before pushing, and resolving any conflicts that may arise.","steps":[{"title":"Push Local Changes to Remote","body":["To complete this challenge, you will use the Git repository git-playground from your GitHub account, which comes from a fork of https://github.com/labex-labs/git-playground.git. You have made some changes to the master branch and want to push them to the remote repository.","• Clone the repository to your local machine from https://github.com/your-username/git-playground, navigate to the directory and configure the identity. • Ensure that your local branch is up to date with the remote branch. • After pulling the latest changes from the remote branch, you can write \"hello,world\" to the file1.txt file on the master branch, add the staging area and commit it with the message \"Added new feature \". • Finally, push the changes to the remote repository.","This is the result of running git log:"],"code":[{"lang":"shell","text":"commit 1f1949955387a1549f1bb5286d3d0a2b993f87e0 (HEAD -> master,origin/master,origin/HEAD)\nAuthor: xiaoshengyunan <@users.noreply.github.com>\nDate:   Fri Jul 21 19:26:57 2023 +0800\n\n    Added new feature"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit push\n```\n\n```shell\n# Fork from https://github.com/labex-labs/git-playground.git\ngit clone https://github.com/your-username/git-playground.git\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\necho \"hello,world\" >> file1.txt\ngit add .\ngit commit -m \"Added new feature\"\ngit push origin master # The remote `master` branch is now up to date with the local branch\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-rebase-onto-another-branch":{"intro":"In this challenge, you will learn how to rebase a branch onto another branch in Git, which allows you to incorporate changes from one branch into another while maintaining a clean and linear history.","steps":[{"title":"Rebase onto Another Branch","body":["As a developer, you are working on a project with multiple branches. You have made changes to your branch and want to incorporate those changes into another branch. However, you don't want to merge the branches because you want to maintain a clean and linear history.","For this challenge, let's use the repository from https://github.com/labex-labs/git-playground.","• Navigate to the directory and configure the identity. • Create and switch to a branch called one-branch. • Add \"hello,world\" to the README.md file, add it to the staging area and commit it with the message \"Added some changes to README.md\". • Switch to the master branch. • Ensure that your local master branch is up to date with the remote repository. • Rebase the one-branch onto the master branch. • Resolve any conflicts that arise during the rebase process.","This is the result of running git log:"],"code":[{"lang":"shell","text":"commit eccff423dd6bf5335f76f2f364fa3b95130ff805 (HEAD -> master, one-branch)\nAuthor: xiaoshengyunan <@users.noreply.github.com>\nDate:   Sat Jul 22 23:10:04 2023 +0800\n\n    Added some changes to README.md"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit checkout <branch>\ngit rebase <base-branch>\n```\n\n```shell\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\ngit checkout -b one-branch\necho \"hello,world\" >> README.md\ngit add .\ngit commit -am \"Added some changes to README.md\"\ngit checkout master\ngit pull\ngit rebase feature-branch\n# `master` is rebased onto `feature-branch`\ngit log\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-remove-a-file-from-the-last-commit":{"intro":"In this challenge, you will learn how to remove a file from the last commit in a Git repository without changing the commit message.","steps":[{"title":"Remove a File from the Last Commit","body":["Remove a File from the Last Commit","You have added a file to the last commit that you didn't intend to include. You want to remove the file from the last commit without changing its message.","For this challenge, let's use the repository from https://github.com/labex-labs/git-playground. Suppose you have a Git repository named git-playground with a file named file2.txt that you accidentally added to the last commit.","• Navigate to the repository directory and configure your GitHub identity . • Remove the specified file2.txt from the index. • Update the contents of the last commit, without changing its message."],"code":[{"lang":"shell","text":"On branch master\n\nChanges to be committed:\n(use \"git restore --staged <file>...\" to unstage)\ndeleted: file2.txt\n\nUntracked files:\n(use \"git add <file>...\" to include in what will be committed)\nfile2.txt"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit rm —-cached <file>\ngit commit —-amend\n```\n\n```shell\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\ngit rm --cached \"file2.txt\"\ngit status\ngit commit --amend --allow-empty\n# Removes `file2.txt` from the last commit\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-rename-remote-branch":{"intro":"In Git, a branch is a lightweight movable pointer to a commit. Renaming a branch is a common task in Git. However, renaming a branch both locally and on the remote can be a bit tricky. In this challenge, you will learn how to rename a remote branch in Git.","steps":[{"title":"Rename Remote Branch","body":["To complete this challenge, you will use the Git repository git-playground from your GitHub account, which comes from a fork of https://github.com/labex-labs/git-playground.git. Please uncheck \"Copy master branch only\" when forking.","You have a Git repository named https://github.com/your-username/git-playground. You have created a branch named feature-branch and pushed it to the remote. Now you want to rename the branch to new-feature-1 both locally and on the remote.","• Clone the repository, navigate to the directory and configure the identity. • Switch to the named feature-branch branch. • Rename the branch both locally and on the remote. • Verify that the branch has been renamed.","This is the result of running git branch -a:"],"code":[{"lang":"shell","text":"* master\nnew-feature-1\nremotes/origin/HEAD - > origin/master\nremotes/origin/master\nremotes/origin/new-feature-1"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit branch -m <old-name> <new-name>\ngit push origin --delete <old-name>\ngit checkout <new-name>\ngit push origin -u <new-name>\n```\n\n```shell\n# Fork from https://github.com/labex-labs/git-playground.git\ngit clone https://github.com/your-username/git-playground.git\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\ngit checkout feature-branch\ngit branch -m feature-branch new-feature-1 # Renamed the local branch to `new-feature-1`\ngit push origin --delete feature-branch\ngit push origin -u new-feature-1 # Renames the remote branch to `new-feature-1`\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-reset-local-master-branch-to-match-remote":{"intro":"When working with Git, it is common to have a local branch that is out of sync with its remote counterpart. This can happen when changes are made to the remote branch that are not reflected in the local branch. In such cases, it is necessary to reset the local branch to match the remote branch. This challenge will guide you through the steps to reset the local master branch to match the one on the remote.","steps":[{"title":"Reset Local Master Branch to Match Remote","body":["Reset Local Master Branch to Match Remote","You have been working on a project and have made changes to the local master branch. However, you realize that the remote master branch has been updated with new changes that you do not have in your local branch. You need to reset the local master branch to match the one on the remote.","• Switch to the master branch. • Retrieve the latest updates from the remote. • View the commit history of the current branch. • Reset the local master branch to match the one on the remote. • Verify that the local master branch is now up to date with the remote master branch."],"code":[{"lang":"shell","text":"[object Object]"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit fetch origin\ngit checkout master\ngit reset --hard origin/master\n```\n\n```shell\ngit fetch origin\ngit checkout master\ngit reset --hard origin/master\n# Local `master` branch is now up to date with remote `master`\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-restore-a-deleted-file":{"intro":"Git is a popular version control system that allows developers to track changes made to their code over time. One of the benefits of using Git is that it allows you to restore deleted files. In this challenge, you will learn how to restore a file that was deleted in a specific commit.","steps":[{"title":"Restore a Deleted File","body":["You are working on a project using Git and accidentally deleted a file named file2.txt that you need. Fortunately, you know the commit where the file was deleted. Your task is to restore the deleted file using Git.","To complete this challenge, you will use the Git repository git-playground from https://github.com/labex-labs/git-playground.git.","• Identifies a commit where a file was deleted with the message \"Added file2.txt\". • Restore the deleted file by checking out the commit before the deletion.","This will restore the file2.txt file to your local repository."],"code":[{"lang":"shell","text":"total 12K\n-rw-r--r-- 1 labex labex 15 Jun 18 18:05 file1.txt\n-rw-r--r-- 1 labex labex 15 Jun 18 18:13 file2.txt\n-rw-r--r-- 1 labex labex 32 Jun 18 18:05 README.md"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit checkout <commit> -- <file>\n```\n\n```shell\ncd git-playground\ngit log --oneline\n# \"file2.txt\" was deleted in the commit `d22f46b`\ngit checkout d22f46b -- file2.txt\n# Restores the file2.txt file\nll\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"}};
